import { ref } from 'vue';
import axios from 'axios';
import { ElMessage } from "element-plus";
export default {
  __name: 'StopContainerDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const container = ref({
      name: ''
    });

    // 打开弹窗
    const openDialog = () => {
      container.value.name = '';
      dialogVisible.value = true;
    };

    // 提交停止请求
    const submitStop = async () => {
      if (!container.value.name) {
        alert('请输入容器名称');
        return;
      }
      try {
        const response = await axios.post(`http://localhost:8081/container/stop/${encodeURIComponent(container.value.name)}`);
        dialogVisible.value = false;
        ElMessage.success(`停止成功：${response.data}`);
      } catch (error) {
        console.error('停止容器出错：', error);
        ElMessage.error('停止失败：' + (error.response?.data || error.message));
      }
    };

    // 向父组件暴露方法
    __expose({
      openDialog
    });
    const __returned__ = {
      dialogVisible,
      container,
      openDialog,
      submitStop,
      ref,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
